users = {
    "u1": {"name": "Ada Lovelace", "country": "UK", "orders": {"o1": {"total": 120}, "o2": {"total": 45}}},
    "u2": {"name": "Grace Hopper", "country": "US", "orders": {"o3": {"total": 300}}},
    "u3": {"name": "Alan Turing", "country": "UK", "orders": {}},
}

def query(collection, field, value):
    return sorted(doc_id for doc_id, doc in collection.items() if doc.get(field) == value)

def subcollection_total(user_doc):
    return sum(order["total"] for order in user_doc["orders"].values())

uk_users = query(users, "country", "UK")
print("UK users:", uk_users)
for uid in sorted(users):
    print(uid, "->", subcollection_total(users[uid]))
